const MODULE_CONTENT = {"en":{"candlestick-patterns":{"faq":[{"q":"Do candlestick patterns work every time?","a":"No. A pattern shows a likely outcome, not a certain one. Its reliability improves with the right context: a clear prior trend, a key level like support or resistance, and confirmation from the next candle and volume."},{"q":"Which pattern is the most reliable?","a":"No single pattern is reliable on its own. Engulfing and morning or evening star patterns at key levels are commonly watched, but all need confirmation and a stop-loss."},{"q":"Can I trade on a pattern alone?","a":"It is risky to do so. Use the pattern as one input. Check the trend, the level, the volume, and your risk per trade before acting."}],"quiz":[{"q":"A hammer is most meaningful when it appears:","o":["After a clear downtrend, at support","In the middle of a sideways range","After a strong uptrend, at resistance","Only on expiry day"],"a":0,"e":"A hammer is a bullish reversal signal after a fall, and it needs confirmation."},{"q":"What does a doji signal?","o":["A certain reversal","Indecision between buyers and sellers","A stop-loss hit","Strong bullish momentum"],"a":1,"e":"A doji has open and close nearly equal, showing balance."},{"q":"The best way to confirm a bullish reversal candle is:","o":["Buy immediately on the pattern candle","Sell because it looks bullish","Wait for the next candle to close above the pattern's high, ideally on rising volume","Ignore volume"],"a":2,"e":"Confirmation reduces false signals."},{"q":"A bullish engulfing pattern means:","o":["A red body covers a green body","Two dojis in a row","A stock split","A green body fully covers the previous red body"],"a":3,"e":"The second green candle's body engulfs the body of the prior red candle."},{"q":"A hanging man is:","o":["A hammer-shaped candle appearing after a rise, which warns of weakness","A bullish reversal after a fall","A doji at the bottom","A marubozu"],"a":0,"e":"The same shape as a hammer is a warning after an uptrend."},{"q":"A shooting star has:","o":["A long lower wick and small body at top","A small body at the bottom and a long upper wick after a rise","No wicks","Equal wicks both ways"],"a":1,"e":"It shows buyers pushed price up but sellers drove it back down."},{"q":"A morning star is:","o":["A bearish three-candle reversal","A single candle with a long upper wick","A bullish three-candle reversal","A chart pattern with a neckline"],"a":2,"e":"Big red, small star with a gap, then big green signals a possible bullish reversal."},{"q":"A dark cloud cover is a:","o":["Bullish pattern after a fall","Doji","Continuation pattern","Bearish reversal after a rise, where the red candle closes below the green midpoint"],"a":3,"e":"The red candle opens above the prior high and closes well into the green body."},{"q":"Three white soldiers indicate:","o":["Three strong green candles closing higher, showing steady buying","Three red candles","A pause only","Dividend"],"a":0,"e":"Three consecutive bullish candles with higher closes show sustained pressure."},{"q":"A bullish harami is best treated as:","o":["A guaranteed buy","A warning that selling is losing strength, not a trigger on its own","A stop-loss","A sell signal"],"a":1,"e":"It suggests weakening selling, but needs confirmation."},{"q":"Which is a common candlestick pattern mistake?","o":["Checking the trend first","Using stops","Trading every pattern you see, including in the middle of nowhere","Checking volume"],"a":2,"e":"Most patterns are noise unless they appear at key levels with a trend."},{"q":"A marubozu candle shows:","o":["Long wicks and small body","Equal open and close","A dividend","A full body with no wicks, showing strong control by one side"],"a":3,"e":"No wicks means one side controlled the entire period."},{"q":"A piercing line is:","o":["A bullish partial reversal after a fall, closing above the midpoint of the prior red candle","A bearish continuation","A doji","A stock split"],"a":0,"e":"The green candle opens below the prior low and closes above the red body's midpoint."},{"q":"Chart patterns such as head and shoulders take longer to form because:","o":["They use fewer candles","They are built from many candles over days or months","They have no breakout","They are only for brokers"],"a":1,"e":"Chart patterns develop over longer periods and define levels such as the neckline."},{"q":"The neckline in a head and shoulders pattern is used to:","o":["Set the broker's fee","Show the dividend","Trigger the trade on a close beyond it","Count the lot size"],"a":2,"e":"A close below the neckline is the confirmation for the bearish pattern."},{"q":"A double bottom usually signals:","o":["A bearish reversal","A continuation of a fall","A stock split","A bullish reversal, confirmed by a break above the neckline"],"a":3,"e":"Two troughs at a similar level, then a break above the neckline."},{"q":"A symmetrical triangle is best described as:","o":["Neutral until a breakout in either direction","Always bullish","Always bearish","A dividend pattern"],"a":0,"e":"Converging highs and lows build energy; the breakout gives the direction."},{"q":"A bull flag is a:","o":["Long decline","Sharp rise followed by a small downward-sloping pause, often a continuation","Doji","Stock split"],"a":1,"e":"A pole then a flag is a common bullish continuation shape."},{"q":"Why wait for a close beyond a chart pattern's level?","o":["To pay a lower fee","The chart does not update otherwise","Many breakouts fail, so a close helps confirm the break","To avoid taxes"],"a":2,"e":"Many breakouts are false; a close beyond the level is stronger evidence."},{"q":"Which practice improves pattern reading the most?","o":["Trading real money from the first day","Following tips","Changing settings often","Marking patterns on past charts and recording what happened next"],"a":3,"e":"Reviewing past examples builds real experience and honest statistics."},{"q":"A pattern works best when:","o":["It appears at a key level, after a trend, and is confirmed","It appears randomly in a range","It appears only on expiry","The broker recommends it"],"a":0,"e":"Location, context and confirmation together make a pattern more useful."}]}},"hi":{"candlestick-patterns":{"faq":[{"q":"क्या कैंडलस्टिक पैटर्न हर बार काम करते हैं?","a":"नहीं। पैटर्न एक संभावित नतीजा दिखाता है, निश्चित नहीं। सही संदर्भ से भरोसा बढ़ता है: साफ़ पिछला ट्रेंड, सपोर्ट या रेज़िस्टेंस जैसा मुख्य स्तर, और अगली कैंडल व वॉल्यूम की पुष्टि।"},{"q":"सबसे भरोसेमंद पैटर्न कौन सा है?","a":"कोई एक पैटर्न अकेले भरोसेमंद नहीं है। मुख्य स्तरों पर एंगल्फ़िंग और मॉर्निंग या ईवनिंग स्टार आम तौर पर देखे जाते हैं, पर सभी को पुष्टि और स्टॉप-लॉस चाहिए।"},{"q":"क्या मैं केवल पैटर्न पर ट्रेड कर सकता हूँ?","a":"ऐसा करना जोखिम भरा है। पैटर्न को एक इनपुट मानें। कार्रवाई से पहले ट्रेंड, स्तर, वॉल्यूम और प्रति ट्रेड जोखिम जाँचें।"}],"quiz":[{"q":"हैमर सबसे ज़्यादा अर्थपूर्ण तब होता है जब वह:","o":["साफ़ गिरावट के बाद, सपोर्ट पर बने","साइडवे रेंज के बीच में बने","मज़बूत तेज़ी के बाद, रेज़िस्टेंस पर बने","केवल एक्सपायरी के दिन बने"],"a":0,"e":"गिरावट के बाद बना हैमर बुलिश पलटाव का संकेत है, और उसे पुष्टि चाहिए।"},{"q":"डोजी क्या संकेत देता है?","o":["निश्चित पलटाव","ख़रीदारों और विक्रेताओं के बीच अनिश्चितता","स्टॉप-लॉस लगना","मज़बूत बुलिश मोमेंटम"],"a":1,"e":"डोजी में ओपन और क्लोज़ लगभग बराबर होते हैं, जो संतुलन दिखाता है।"},{"q":"तेज़ी वाले पलटाव कैंडल की पुष्टि का सबसे अच्छा तरीका क्या है?","o":["पैटर्न कैंडल पर तुरंत ख़रीदना","तेज़ी वाला दिखता है इसलिए बेचना","अगली कैंडल पैटर्न के हाई से ऊपर बंद होने का इंतज़ार, आदर्श रूप से बढ़ते वॉल्यूम के साथ","वॉल्यूम को अनदेखा करना"],"a":2,"e":"पुष्टि झूठे संकेत घटाती है।"},{"q":"बुलिश एंगल्फ़िंग पैटर्न का मतलब है:","o":["लाल बॉडी हरी को ढक ले","लगातार दो डोजी","स्टॉक स्प्लिट","हरी बॉडी पिछली लाल बॉडी को पूरी तरह ढक ले"],"a":3,"e":"दूसरी हरी कैंडल की बॉडी पिछली लाल कैंडल की बॉडी को ढक लेती है।"},{"q":"हैंगिंग मैन है:","o":["बढ़त के बाद हैमर जैसा आकार, जो कमज़ोरी की चेतावनी देता है","गिरावट के बाद बुलिश पलटाव","नीचे की डोजी","मार्बोज़ू"],"a":0,"e":"अपट्रेंड के बाद हैमर जैसा आकार चेतावनी है।"},{"q":"शूटिंग स्टार में होता है:","o":["ऊपर छोटी बॉडी और नीचे लंबी विक","बढ़त के बाद नीचे छोटी बॉडी और ऊपर लंबी विक","कोई विक नहीं","दोनों तरफ़ बराबर विक"],"a":1,"e":"यह दिखाता है कि ख़रीदारों ने कीमत ऊपर धकेली, पर विक्रेताओं ने नीचे ला दी।"},{"q":"मॉर्निंग स्टार है:","o":["तीन कैंडल का बियरिश पलटाव","ऊपरी लंबी विक वाली एक कैंडल","तीन कैंडल का बुलिश पलटाव","नेकलाइन वाला चार्ट पैटर्न"],"a":2,"e":"बड़ी लाल, गैप वाली छोटी स्टार, फिर बड़ी हरी, संभावित तेज़ी का संकेत।"},{"q":"डार्क क्लाउड कवर है:","o":["गिरावट के बाद तेज़ी वाला पैटर्न","डोजी","निरंतरता पैटर्न","बढ़त के बाद बियरिश पलटाव, जहाँ लाल कैंडल हरी के मध्य से नीचे बंद होती है"],"a":3,"e":"लाल कैंडल पिछले हाई से ऊपर खुलती है और हरी बॉडी में काफ़ी नीचे बंद होती है।"},{"q":"थ्री व्हाइट सोल्जर्स दिखाते हैं:","o":["तीन मज़बूत हरी कैंडल जो ऊँचे बंद होती हैं, लगातार ख़रीदारी","तीन लाल कैंडल","केवल ठहराव","डिविडेंड"],"a":0,"e":"लगातार तीन तेज़ी वाली कैंडल, ऊँचे क्लोज़ के साथ, दबाव दिखाती हैं।"},{"q":"बुलिश हरामी को सबसे अच्छा कैसे लिया जाए?","o":["निश्चित ख़रीद","चेतावनी कि बिकवाली कमज़ोर हो रही है, अपने आप में ट्रिगर नहीं","स्टॉप-लॉस","बिक्री संकेत"],"a":1,"e":"यह कमज़ोर होती बिकवाली सुझाता है, पर पुष्टि चाहिए।"},{"q":"कैंडलस्टिक पैटर्न की एक आम गलती कौन सी है?","o":["पहले ट्रेंड जाँचना","स्टॉप लगाना","हर दिखने वाला पैटर्न ट्रेड करना, यहाँ तक कि बीच रेंज में भी","वॉल्यूम जाँचना"],"a":2,"e":"ज़्यादातर पैटर्न शोर हैं, जब तक वे ट्रेंड के साथ मुख्य स्तरों पर न हों।"},{"q":"मार्बोज़ू कैंडल दिखाती है:","o":["लंबी विक और छोटी बॉडी","बराबर ओपन और क्लोज़","डिविडेंड","बिना विक की पूरी बॉडी, एक पक्ष का मज़बूत नियंत्रण"],"a":3,"e":"कोई विक न होने का मतलब है एक पक्ष ने पूरी अवधि पर नियंत्रण रखा।"},{"q":"पियर्सिंग लाइन है:","o":["गिरावट के बाद आंशिक तेज़ी वाला पलटाव, जो पिछली लाल कैंडल के मध्य से ऊपर बंद हो","बियरिश निरंतरता","डोजी","स्टॉक स्प्लिट"],"a":0,"e":"हरी कैंडल पिछले लो से नीचे खुलती है और लाल बॉडी के मध्य से ऊपर बंद होती है।"},{"q":"हेड एंड शोल्डर्स जैसे चार्ट पैटर्न बनने में ज़्यादा समय लेते हैं क्योंकि:","o":["वे कम कैंडल का उपयोग करते हैं","वे दिनों या महीनों में बनी कई कैंडल से बनते हैं","उनमें ब्रेकआउट नहीं होता","वे केवल ब्रोकरों के लिए हैं"],"a":1,"e":"चार्ट पैटर्न लंबी अवधि में बनते हैं और नेकलाइन जैसे स्तर तय करते हैं।"},{"q":"हेड एंड शोल्डर्स में नेकलाइन का उपयोग किसलिए होता है?","o":["ब्रोकर की फ़ीस तय करने के लिए","डिविडेंड दिखाने के लिए","उसके पार क्लोज़ पर ट्रेड लेने के लिए","लॉट साइज़ गिनने के लिए"],"a":2,"e":"नेकलाइन के नीचे क्लोज़ बियरिश पैटर्न की पुष्टि है।"},{"q":"डबल बॉटम आमतौर पर संकेत देता है:","o":["बियरिश पलटाव","गिरावट की निरंतरता","स्टॉक स्प्लिट","तेज़ी वाला पलटाव, नेकलाइन के ऊपर ब्रेक से पुष्टि"],"a":3,"e":"समान स्तर पर दो गर्त, फिर नेकलाइन के ऊपर ब्रेक।"},{"q":"सिमेट्रिकल ट्राएंगल को सबसे अच्छा कैसे वर्णित किया जाए?","o":["किसी भी दिशा में ब्रेकआउट तक तटस्थ","हमेशा तेज़ी वाला","हमेशा मंदी वाला","डिविडेंड पैटर्न"],"a":0,"e":"एक-दूसरे की ओर बढ़ते हाई और लो ऊर्जा जमा करते हैं; ब्रेकआउट दिशा देता है।"},{"q":"बुल फ़्लैग है:","o":["लंबी गिरावट","तेज़ उछाल, फिर नीचे झुकता छोटा ठहराव, अक्सर निरंतरता","डोजी","स्टॉक स्प्लिट"],"a":1,"e":"पोल और फ़्लैग तेज़ी की निरंतरता का आम आकार है।"},{"q":"चार्ट पैटर्न के स्तर के पार क्लोज़ का इंतज़ार क्यों करें?","o":["कम फ़ीस देने के लिए","चार्ट अन्यथा अपडेट नहीं होता","कई ब्रेकआउट विफल होते हैं, इसलिए क्लोज़ ब्रेक की पुष्टि में मदद करता है","टैक्स से बचने के लिए"],"a":2,"e":"कई ब्रेकआउट झूठे होते हैं; स्तर के पार क्लोज़ मज़बूत सबूत है।"},{"q":"पैटर्न पढ़ने में सबसे ज़्यादा कौन सी आदत सुधार लाती है?","o":["पहले दिन से असली पैसे से ट्रेड","टिप्स का पालन","सेटिंग बार-बार बदलना","पिछले चार्ट पर पैटर्न चिह्नित करना और आगे क्या हुआ लिखना"],"a":3,"e":"पिछले उदाहरणों की समीक्षा असली अनुभव और ईमानदार आँकड़े बनाती है।"},{"q":"पैटर्न सबसे अच्छा तब काम करता है जब वह:","o":["मुख्य स्तर पर, ट्रेंड के बाद बने और पुष्टि हो","रेंज में अचानक दिखे","केवल एक्सपायरी पर दिखे","ब्रोकर उसकी सिफ़ारिश करे"],"a":0,"e":"स्थान, संदर्भ और पुष्टि मिलकर पैटर्न को ज़्यादा उपयोगी बनाते हैं।"}]}}};
const PATTERNS = [{"id":"hammer","kind":"candle","bias":"bullish","file":"hammer.svg","name":{"en":"Hammer","hi":"हैमर"},"what":{"en":"A small body near the top with a long lower wick, at least twice the body. Sellers pushed price down, but buyers lifted it back before the close.","hi":"ऊपर के पास छोटी बॉडी और नीचे की लंबी विक, जो बॉडी से कम से कम दोगुनी हो। विक्रेताओं ने कीमत गिराई, पर ख़रीदारों ने बंद होने से पहले वापस ऊपर धकेल दी।"},"where":{"en":"After a clear downtrend, at a support level or a prior low.","hi":"साफ़ गिरावट के बाद, सपोर्ट या पिछले निचले स्तर पर।"},"confirm":{"en":"The next candle closes above the hammer's high.","hi":"अगली कैंडल हैमर के हाई से ऊपर बंद हो।"},"mistake":{"en":"Using it in a sideways market or without a prior fall. There it means little.","hi":"बिना गिरावट के या साइडवे बाज़ार में इस पर भरोसा करना; वहाँ इसका ज़्यादा अर्थ नहीं।"}},{"id":"inverted-hammer","kind":"candle","bias":"bullish","file":"inverted-hammer.svg","name":{"en":"Inverted hammer","hi":"इन्वर्टेड हैमर"},"what":{"en":"A small body at the bottom with a long upper wick, after a fall. Buyers tried to push price up. Sellers held it down, but the attempt matters.","hi":"नीचे छोटी बॉडी और ऊपर लंबी विक, गिरावट के बाद। ख़रीदारों ने कीमत ऊपर ले जाने की कोशिश की; बिक्री ने उसे रोका, पर कोशिश मायने रखती है।"},"where":{"en":"After a downtrend, at support.","hi":"गिरावट के बाद सपोर्ट पर।"},"confirm":{"en":"The next candle is green and closes above the inverted hammer's high.","hi":"अगली हरी कैंडल इसके हाई से ऊपर बंद हो।"},"mistake":{"en":"Trading on it alone. The upper wick shows a failed rally, so confirmation is required.","hi":"केवल इसी पर ट्रेड करना; पुष्टि ज़रूरी है, क्योंकि ऊपरी विक एक विफल उछाल दिखाती है।"}},{"id":"hanging-man","kind":"candle","bias":"bearish","file":"hanging-man.svg","name":{"en":"Hanging man","hi":"हैंगिंग मैन"},"what":{"en":"Same shape as a hammer, but after an uptrend. Price fell sharply during the day before recovering, a sign that buyers are losing control.","hi":"हैमर जैसा आकार, पर अपट्रेंड के बाद। दिन में कीमत तेज़ गिरी और फिर उठी, जो ख़रीदारों की पकड़ ढीली होने का संकेत है।"},"where":{"en":"After a strong rally, near resistance or a recent high.","hi":"तेज़ तेज़ी के बाद, रेज़िस्टेंस या ऊँचाई के पास।"},"confirm":{"en":"The next candle closes below the hanging man's body.","hi":"अगली कैंडल इसकी बॉडी के नीचे बंद हो।"},"mistake":{"en":"Shorting just because it appears. A rally can keep going for days.","hi":"सिर्फ़ दिखने के आधार पर शॉर्ट करना; तेज़ी कई दिन चल सकती है।"}},{"id":"shooting-star","kind":"candle","bias":"bearish","file":"shooting-star.svg","name":{"en":"Shooting star","hi":"शूटिंग स्टार"},"what":{"en":"Small body at the bottom with a long upper wick, after a rise. Buyers pushed price up hard, but sellers drove it back down.","hi":"ऊपर की ओर लंबी विक और नीचे छोटी बॉडी, तेज़ी के बाद। ख़रीदारों ने कीमत ऊपर धकेली, पर विक्रेताओं ने उसे नीचे ला दिया।"},"where":{"en":"After an uptrend, at resistance.","hi":"अपट्रेंड के बाद, रेज़िस्टेंस पर।"},"confirm":{"en":"The next candle is red and closes below the shooting star's body.","hi":"अगली लाल कैंडल इसकी बॉडी के नीचे बंद हो।"},"mistake":{"en":"Using it without an uptrend. The signal depends on the prior rise.","hi":"अपट्रेंड के बिना इसका उपयोग; संकेत पहले की तेज़ी पर निर्भर है।"}},{"id":"doji","kind":"candle","bias":"neutral","file":"doji.svg","name":{"en":"Doji","hi":"डोजी"},"what":{"en":"Open and close are equal or nearly equal, so the body is a thin line. Buyers and sellers are balanced.","hi":"ओपन और क्लोज़ बराबर या लगभग बराबर, इसलिए बॉडी पतली रेखा जैसी। ख़रीदार और विक्रेता बराबरी पर हैं।"},"where":{"en":"At the end of a strong trend, as a sign of a possible pause.","hi":"मज़बूत ट्रेंड के अंत में, संभावित विराम के संकेत के रूप में।"},"confirm":{"en":"The next candle moves in a new direction with volume.","hi":"अगली कैंडल नई दिशा में वॉल्यूम के साथ चले।"},"mistake":{"en":"Treating every doji as a reversal. In a quiet market they are common and mean little.","hi":"हर डोजी को पलटाव मानना; शांत बाज़ार में ये आम हैं और कुछ नहीं बताते।"}},{"id":"dragonfly-doji","kind":"candle","bias":"bullish","file":"dragonfly-doji.svg","name":{"en":"Dragonfly doji","hi":"ड्रैगनफ़्लाई डोजी"},"what":{"en":"Open, high and close at the top, with a long lower wick. Sellers pushed price down, and buyers recovered all of it.","hi":"ऊपर खुला, ऊपर बंद और ऊपर हाई, नीचे लंबी विक। विक्रेताओं ने नीचे धकेला, ख़रीदारों ने सारी गिरावट वापस ले ली।"},"where":{"en":"After a downtrend, at support.","hi":"गिरावट के बाद, सपोर्ट पर।"},"confirm":{"en":"A green candle follows and closes higher.","hi":"इसके बाद एक हरी कैंडल ऊपर बंद हो।"},"mistake":{"en":"Ignoring the trend. Without a fall before it, the shape has little meaning.","hi":"ट्रेंड को नज़रअंदाज़ करना; पहले गिरावट न हो तो आकृति का ज़्यादा अर्थ नहीं।"}},{"id":"gravestone-doji","kind":"candle","bias":"bearish","file":"gravestone-doji.svg","name":{"en":"Gravestone doji","hi":"ग्रेवस्टोन डोजी"},"what":{"en":"Open, low and close at the bottom, with a long upper wick. Buyers pushed price up, but it closed back at the low.","hi":"नीचे खुला, नीचे बंद और नीचे लो, ऊपर लंबी विक। ख़रीदारों ने कीमत ऊपर ले जाई, पर वह वापस निचले स्तर पर बंद हुई।"},"where":{"en":"After an uptrend, near resistance.","hi":"अपट्रेंड के बाद, रेज़िस्टेंस के पास।"},"confirm":{"en":"The next candle is red and closes lower.","hi":"अगली लाल कैंडल नीचे बंद हो।"},"mistake":{"en":"Trading it in a sideways market, where it appears often.","hi":"साइडवे बाज़ार में इस पर ट्रेड करना, जहाँ यह अक्सर दिखता है।"}},{"id":"marubozu","kind":"candle","bias":"bullish","file":"marubozu.svg","name":{"en":"Marubozu","hi":"मार्बोज़ू"},"what":{"en":"A full body with no wicks. For a bullish one, the open was the low and the close was the high. Buyers controlled the whole session.","hi":"बिना विक की पूरी बॉडी: तेज़ी वाली में ओपन ही लो और क्लोज़ ही हाई। सत्र पर ख़रीदारों का पूरा नियंत्रण।"},"where":{"en":"As a breakout candle or at the start of a trend, with high volume.","hi":"ब्रेकआउट कैंडल के रूप में या ट्रेंड की शुरुआत में, ज़्यादा वॉल्यूम के साथ।"},"confirm":{"en":"Follow-through: the next candles keep rising.","hi":"आगे की कैंडल भी ऊपर जाएँ।"},"mistake":{"en":"Chasing a large marubozu after the move has already extended.","hi":"बड़ी मार्बोज़ू के बाद चाल पहले ही बढ़ चुकी हो तो पीछा करना।"}},{"id":"bullish-engulfing","kind":"candle","bias":"bullish","file":"bullish-engulfing.svg","name":{"en":"Bullish engulfing","hi":"बुलिश एंगल्फ़िंग"},"what":{"en":"A green candle whose body fully covers the previous red candle's body. Buyers overpowered sellers in one session.","hi":"हरी कैंडल जिसकी बॉडी पिछली लाल कैंडल की बॉडी को पूरी तरह ढक ले। एक सत्र में ख़रीदारों ने विक्रेताओं को हरा दिया।"},"where":{"en":"After a downtrend, at support.","hi":"गिरावट के बाद, सपोर्ट पर।"},"confirm":{"en":"The next candle holds above the engulfing candle's low.","hi":"अगली कैंडल इंगल्फ़िंग कैंडल के लो से ऊपर रहे।"},"mistake":{"en":"Treating a small engulfing candle as strong after a large red one. It is weaker than it looks.","hi":"छोटी इंगल्फ़िंग कैंडल को बड़ी लाल कैंडल के बाद भी उतना ही मज़बूत मानना।"}},{"id":"bearish-engulfing","kind":"candle","bias":"bearish","file":"bearish-engulfing.svg","name":{"en":"Bearish engulfing","hi":"बेयरिश एंगल्फ़िंग"},"what":{"en":"A red candle whose body fully covers the previous green candle's body. Sellers overpowered buyers in one session.","hi":"लाल कैंडल जिसकी बॉडी पिछली हरी कैंडल की बॉडी को पूरी तरह ढक ले। एक सत्र में विक्रेताओं ने ख़रीदारों को हरा दिया।"},"where":{"en":"After an uptrend, near resistance.","hi":"अपट्रेंड के बाद, रेज़िस्टेंस पर।"},"confirm":{"en":"The next candle closes below the engulfing candle's low.","hi":"अगली कैंडल इंगल्फ़िंग कैंडल के लो से नीचे बंद हो।"},"mistake":{"en":"Shorting into a strong trend without other evidence.","hi":"मज़बूत ट्रेंड में बिना अन्य सबूत के शॉर्ट करना।"}},{"id":"bullish-harami","kind":"candle","bias":"bullish","file":"bullish-harami.svg","name":{"en":"Bullish harami","hi":"बुलिश हरामी"},"what":{"en":"A big red candle followed by a small green candle inside its body. Selling pressure is losing strength.","hi":"एक बड़ी लाल कैंडल के बाद उसकी बॉडी के अंदर एक छोटी हरी कैंडल। बिकवाली का ज़ोर कम हो रहा है।"},"where":{"en":"After a downtrend.","hi":"गिरावट के बाद।"},"confirm":{"en":"A strong green candle breaks above the big red candle's high.","hi":"एक मज़बूत हरी कैंडल बड़ी लाल कैंडल के हाई से ऊपर जाए।"},"mistake":{"en":"Treating a harami as a strong signal on its own. It is a warning, not a trigger.","hi":"हरामी को अकेले मज़बूत संकेत मानना; यह चेतावनी है, ट्रिगर नहीं।"}},{"id":"piercing-line","kind":"candle","bias":"bullish","file":"piercing-line.svg","name":{"en":"Piercing line","hi":"पियर्सिंग लाइन"},"what":{"en":"A red candle, then a green candle that opens below the red candle's low and closes above its midpoint. Buyers recovered half or more of the drop.","hi":"एक लाल कैंडल, फिर हरी कैंडल जो लाल के लो से नीचे खुले और बॉडी के मध्य से ऊपर बंद हो। ख़रीदारों ने गिरावट का आधा या ज़्यादा वापस ले लिया।"},"where":{"en":"After a downtrend.","hi":"गिरावट के बाद।"},"confirm":{"en":"The next candle keeps rising.","hi":"अगली कैंडल भी ऊपर जाए।"},"mistake":{"en":"Expecting a full reversal from a close just above the midpoint.","hi":"मध्य से थोड़ा ऊपर बंद होने पर पूरे पलटाव की उम्मीद करना।"}},{"id":"dark-cloud-cover","kind":"candle","bias":"bearish","file":"dark-cloud-cover.svg","name":{"en":"Dark cloud cover","hi":"डार्क क्लाउड कवर"},"what":{"en":"A green candle, then a red candle that opens above the green candle's high and closes below its midpoint. Sellers took back half or more of the rally.","hi":"एक हरी कैंडल, फिर लाल कैंडल जो हरी के हाई से ऊपर खुले और बॉडी के मध्य से नीचे बंद हो। विक्रेताओं ने आधी या ज़्यादा तेज़ी वापस ले ली।"},"where":{"en":"After an uptrend.","hi":"अपट्रेंड के बाद।"},"confirm":{"en":"The next candle falls further.","hi":"अगली कैंडल और नीचे जाए।"},"mistake":{"en":"Selling on the first red candle without checking the trend.","hi":"ट्रेंड देखे बिना पहली लाल कैंडल पर बेचना।"}},{"id":"morning-star","kind":"candle","bias":"bullish","file":"morning-star.svg","name":{"en":"Morning star","hi":"मॉर्निंग स्टार"},"what":{"en":"Three candles: a big red, a small star with a gap down, then a big green that closes above the midpoint of the first. Selling fades and buyers take over.","hi":"तीन कैंडल: एक बड़ी लाल, फिर गैप डाउन वाली छोटी स्टार, फिर बड़ी हरी जो पहली की बॉडी के मध्य से ऊपर बंद हो। बिकवाली कमज़ोर पड़ती है और ख़रीदार हावी होते हैं।"},"where":{"en":"After a downtrend, at support.","hi":"गिरावट के बाद, सपोर्ट पर।"},"confirm":{"en":"The following candle continues higher.","hi":"अगली कैंडल भी ऊपर जाए।"},"mistake":{"en":"Waiting for a perfect shape. Real examples often have small gaps, or none at all.","hi":"परफ़ेक्ट आकृति का इंतज़ार करना; असली उदाहरणों में अक्सर छोटे गैप होते हैं या बिल्कुल नहीं।"}},{"id":"evening-star","kind":"candle","bias":"bearish","file":"evening-star.svg","name":{"en":"Evening star","hi":"ईवनिंग स्टार"},"what":{"en":"Three candles: a big green, a small star with a gap up, then a big red that closes below the midpoint of the first. Buying fades and sellers take over.","hi":"तीन कैंडल: बड़ी हरी, गैप अप वाली छोटी स्टार, फिर बड़ी लाल जो पहली की बॉडी के मध्य से नीचे बंद हो। ख़रीदारी कमज़ोर और विक्रेता हावी।"},"where":{"en":"After an uptrend, near resistance.","hi":"अपट्रेंड के बाद, रेज़िस्टेंस पर।"},"confirm":{"en":"The following candle falls.","hi":"अगली कैंडल नीचे जाए।"},"mistake":{"en":"Shorting just because the pattern shows up inside a sideways range.","hi":"साइडवे रेंज में पैटर्न दिखने भर से शॉर्ट करना।"}},{"id":"three-white-soldiers","kind":"candle","bias":"bullish","file":"three-white-soldiers.svg","name":{"en":"Three white soldiers","hi":"थ्री व्हाइट सोल्जर्स"},"what":{"en":"Three consecutive green candles, each opening within the previous body and closing higher. Steady buying pressure.","hi":"लगातार तीन हरी कैंडल, हर एक पिछली बॉडी के भीतर खुले और ऊँचा बंद हो। लगातार ख़रीदारी का दबाव।"},"where":{"en":"After a downtrend, as a sign of a new uptrend.","hi":"गिरावट के बाद, नए अपट्रेंड के संकेत के रूप में।"},"confirm":{"en":"Volume rises and the trend holds on the next pullback.","hi":"वॉल्यूम बढ़े और अगले पुलबैक पर ट्रेंड बना रहे।"},"mistake":{"en":"Entering after the third candle, when price has already run far.","hi":"तीसरी कैंडल के बाद चाल पहले ही काफ़ी आगे निकल चुकी हो, तब प्रवेश करना।"}},{"id":"three-black-crows","kind":"candle","bias":"bearish","file":"three-black-crows.svg","name":{"en":"Three black crows","hi":"थ्री ब्लैक क्रोज़"},"what":{"en":"Three consecutive red candles, each opening within the previous body and closing lower. Steady selling pressure.","hi":"लगातार तीन लाल कैंडल, हर एक पिछली बॉडी के भीतर खुले और नीचे बंद हो। लगातार बिकवाली का दबाव।"},"where":{"en":"After an uptrend, as a sign that a downtrend is starting.","hi":"अपट्रेंड के बाद, नई गिरावट शुरू होने के संकेत के रूप में।"},"confirm":{"en":"Price stays below the third candle's low.","hi":"कीमत तीसरी कैंडल के लो से नीचे टिकी रहे।"},"mistake":{"en":"Shorting after the crows have already fallen far. Late entries often get a bounce.","hi":"कौवे पहले ही काफ़ी गिर चुके हों तब शॉर्ट करना; देर से प्रवेश पर अक्सर उछाल आता है।"}},{"id":"head-and-shoulders","kind":"chart","bias":"bearish","file":"head-and-shoulders.svg","name":{"en":"Head and shoulders","hi":"हेड एंड शोल्डर्स"},"what":{"en":"Three peaks: a left shoulder, a higher head, and a right shoulder at about the level of the left one. A line (neckline) joins the troughs.","hi":"तीन शिखर: बायाँ कंधा, ऊँचा सिर, और दायाँ कंधा जो बाएँ के लगभग बराबर। गर्दन-रेखा (neckline) गर्तों को जोड़ती है।"},"where":{"en":"After an uptrend, as a reversal signal.","hi":"अपट्रेंड के बाद, पलटाव संकेत के रूप में।"},"confirm":{"en":"A close below the neckline, ideally with volume.","hi":"गर्दन-रेखा के नीचे क्लोज़, आदर्श रूप से वॉल्यूम के साथ।"},"mistake":{"en":"Predicting the drop before the neckline breaks.","hi":"गर्दन-रेखा टूटने से पहले गिरावट का अनुमान लगाना।"}},{"id":"inverse-head-and-shoulders","kind":"chart","bias":"bullish","file":"inverse-head-and-shoulders.svg","name":{"en":"Inverse head and shoulders","hi":"इनवर्स हेड एंड शोल्डर्स"},"what":{"en":"The mirror image: three troughs, with the middle one the deepest. The neckline joins the peaks.","hi":"दर्पण छवि: तीन गर्त, जिनमें बीच वाला सबसे गहरा। गर्दन-रेखा शिखरों को जोड़ती है।"},"where":{"en":"After a downtrend, as a bullish reversal.","hi":"गिरावट के बाद, तेज़ी के पलटाव के रूप में।"},"confirm":{"en":"A close above the neckline.","hi":"गर्दन-रेखा के ऊपर क्लोज़।"},"mistake":{"en":"Entering inside the pattern before the break.","hi":"टूटने से पहले पैटर्न के भीतर प्रवेश करना।"}},{"id":"double-top","kind":"chart","bias":"bearish","file":"double-top.svg","name":{"en":"Double top","hi":"डबल टॉप"},"what":{"en":"Two peaks at about the same level with a dip between them. The support line under the dip is the key level.","hi":"लगभग एक ही स्तर पर दो शिखर, बीच में गिरावट। गिरावट के नीचे का सपोर्ट स्तर मुख्य है।"},"where":{"en":"After an uptrend, when buyers fail twice at the same price.","hi":"अपट्रेंड के बाद, जब ख़रीदार उसी कीमत पर दो बार विफल हों।"},"confirm":{"en":"A close below the support level under the dip.","hi":"उस सपोर्ट स्तर के नीचे क्लोज़।"},"mistake":{"en":"Calling it a double top too early, before the second peak is confirmed.","hi":"दूसरे शिखर की पुष्टि से पहले इसे डबल टॉप कह देना।"}},{"id":"double-bottom","kind":"chart","bias":"bullish","file":"double-bottom.svg","name":{"en":"Double bottom","hi":"डबल बॉटम"},"what":{"en":"Two troughs at about the same level with a peak between them. The neckline at that peak is the key level.","hi":"लगभग एक ही स्तर पर दो गर्त, बीच में शिखर। उस शिखर पर गर्दन-रेखा मुख्य स्तर है।"},"where":{"en":"After a downtrend, when sellers fail twice at the same price.","hi":"गिरावट के बाद, जब विक्रेता उसी कीमत पर दो बार विफल हों।"},"confirm":{"en":"A close above the neckline.","hi":"गर्दन-रेखा के ऊपर क्लोज़।"},"mistake":{"en":"Buying the second trough before the neckline breaks.","hi":"गर्दन-रेखा टूटने से पहले दूसरे गर्त पर ख़रीदना।"}},{"id":"ascending-triangle","kind":"chart","bias":"bullish","file":"ascending-triangle.svg","name":{"en":"Ascending triangle","hi":"एसेंडिंग ट्राएंगल"},"what":{"en":"A flat resistance line on top with rising lows underneath. Buyers keep pressing toward the same ceiling.","hi":"ऊपर सपाट रेज़िस्टेंस रेखा और नीचे बढ़ते लो। ख़रीदार उसी छत की ओर लगातार दबाव बनाते हैं।"},"where":{"en":"In an uptrend, as a continuation setup.","hi":"अपट्रेंड में, निरंतरता के सेटअप के रूप में।"},"confirm":{"en":"A breakout above resistance with rising volume.","hi":"रेज़िस्टेंस के ऊपर ब्रेकआउट, बढ़ते वॉल्यूम के साथ।"},"mistake":{"en":"Buying before the breakout just because the lows are rising.","hi":"सिर्फ़ लो बढ़ रहे हैं इसलिए ब्रेकआउट से पहले ख़रीदना।"}},{"id":"symmetrical-triangle","kind":"chart","bias":"neutral","file":"symmetrical-triangle.svg","name":{"en":"Symmetrical triangle","hi":"सिमेट्रिकल ट्राएंगल"},"what":{"en":"Highs fall and lows rise, converging to a point. Energy builds until price breaks out.","hi":"ऊँचे हाई घटते हैं और लो बढ़ते हैं, और एक बिंदु पर मिलते हैं। ब्रेकआउट तक ऊर्जा जमा होती है।"},"where":{"en":"During consolidation after a trend.","hi":"ट्रेंड के बाद के समेकन (consolidation) में।"},"confirm":{"en":"A breakout with volume. Wait for it.","hi":"वॉल्यूम के साथ ब्रेकआउट; तब तक इंतज़ार करें।"},"mistake":{"en":"Predicting the direction before the break.","hi":"ब्रेक से पहले दिशा का अनुमान लगाना।"}},{"id":"bull-flag","kind":"chart","bias":"bullish","file":"bull-flag.svg","name":{"en":"Bull flag","hi":"बुल फ़्लैग"},"what":{"en":"A sharp rise (the pole), then a small downward-sloping channel (the flag) as price pauses.","hi":"तेज़ उछाल (पोल), फिर ठहराव के दौरान नीचे की ओर झुकता छोटा चैनल (फ़्लैग)।"},"where":{"en":"After a strong move up, as a continuation.","hi":"मज़बूत चाल के बाद, निरंतरता के रूप में।"},"confirm":{"en":"A breakout above the flag's upper line on volume.","hi":"फ़्लैग की ऊपरी रेखा के ऊपर वॉल्यूम के साथ ब्रेकआउट।"},"mistake":{"en":"Expecting a flag after a weak, slow rise. The pole must be sharp.","hi":"धीमी, कमज़ोर चाल के बाद फ़्लैग की उम्मीद करना; पोल तेज़ होना चाहिए।"}},{"id":"cup-and-handle","kind":"chart","bias":"bullish","file":"cup-and-handle.svg","name":{"en":"Cup and handle","hi":"कप एंड हैंडल"},"what":{"en":"A rounded bottom (the cup), then a small dip (the handle) before the breakout.","hi":"गोलाकार तल (कप), फिर ब्रेकआउट से पहले छोटी गिरावट (हैंडल)।"},"where":{"en":"After a long decline and recovery, in an uptrend.","hi":"लंबी गिरावट और रिकवरी के बाद।"},"confirm":{"en":"A breakout above the rim, with volume.","hi":"रिम के ऊपर वॉल्यूम के साथ ब्रेकआउट।"},"mistake":{"en":"Buying during the handle, before the breakout.","hi":"ब्रेकआउट से पहले हैंडल के दौरान ख़रीदना।"}},{"id":"spinning-top","kind":"candle","bias":"neutral","file":"spinning-top.svg","name":{"en":"Spinning top","hi":"स्पिनिंग टॉप"},"what":{"en":"A small body with long wicks on both sides. Price moved up and down during the period but closed near where it opened.","hi":"छोटी बॉडी और दोनों तरफ़ लंबी विक। अवधि में कीमत ऊपर-नीचे गई, पर लगभग वहीं बंद हुई जहाँ खुली थी।"},"where":{"en":"After a strong move, as a sign the trend may pause.","hi":"मज़बूत चाल के बाद, संकेत कि ट्रेंड रुक सकता है।"},"confirm":{"en":"The next candle moves clearly in one direction, with volume.","hi":"अगली कैंडल वॉल्यूम के साथ साफ़ एक दिशा में चले।"},"mistake":{"en":"Treating it as a reversal on its own. It only shows indecision.","hi":"इसे अकेले पलटाव मानना। यह केवल अनिश्चितता दिखाता है।"}},{"id":"tweezer-bottom","kind":"candle","bias":"bullish","file":"tweezer-bottom.svg","name":{"en":"Tweezer bottom","hi":"ट्वीज़र बॉटम"},"what":{"en":"Two candles in a row with the same low. The first is red and the second is green, so sellers failed twice to push below that level.","hi":"लगातार दो कैंडल जिनका लो एक जैसा हो। पहली लाल और दूसरी हरी, यानी विक्रेता उस स्तर के नीचे दो बार नहीं टिक सके।"},"where":{"en":"After a clear downtrend, at support.","hi":"साफ़ गिरावट के बाद, सपोर्ट पर।"},"confirm":{"en":"Price closes above the high of the second candle.","hi":"कीमत दूसरी कैंडल के हाई के ऊपर क्लोज़ हो।"},"mistake":{"en":"Ignoring the trend. Two equal lows in a sideways market mean little.","hi":"ट्रेंड को अनदेखा करना। साइडवे बाज़ार में दो बराबर लो का ज़्यादा अर्थ नहीं।"}},{"id":"tweezer-top","kind":"candle","bias":"bearish","file":"tweezer-top.svg","name":{"en":"Tweezer top","hi":"ट्वीज़र टॉप"},"what":{"en":"Two candles with the same high after a rise. Buyers pushed to the same level twice and were rejected.","hi":"बढ़त के बाद दो कैंडल जिनका हाई एक जैसा हो। ख़रीदार उसी स्तर तक दो बार गए और दोनों बार लौटा दिए गए।"},"where":{"en":"After an uptrend, at resistance.","hi":"अपट्रेंड के बाद, रेज़िस्टेंस पर।"},"confirm":{"en":"Price closes below the low of the second candle.","hi":"कीमत दूसरी कैंडल के लो के नीचे क्लोज़ हो।"},"mistake":{"en":"Shorting at the first high without waiting for the close below.","hi":"नीचे क्लोज़ का इंतज़ार किए बिना पहले हाई पर शॉर्ट करना।"}},{"id":"three-inside-up","kind":"candle","bias":"bullish","file":"three-inside-up.svg","name":{"en":"Three inside up","hi":"थ्री इनसाइड अप"},"what":{"en":"A bullish harami (a small green candle inside a large red one), followed by a third green candle that closes above the first candle's high.","hi":"बुलिश हरामी (बड़ी लाल कैंडल के अंदर छोटी हरी), फिर तीसरी हरी कैंडल जो पहली के हाई के ऊपर बंद हो।"},"where":{"en":"After a downtrend, at support.","hi":"गिरावट के बाद, सपोर्ट पर।"},"confirm":{"en":"The third candle's close above the first candle's high is the confirmation.","hi":"तीसरी कैंडल का पहली के हाई के ऊपर क्लोज़ ही पुष्टि है।"},"mistake":{"en":"Entering on the harami alone, before the third candle confirms.","hi":"तीसरी कैंडल की पुष्टि से पहले सिर्फ़ हरामी पर एंट्री।"}},{"id":"rectangle","kind":"chart","bias":"neutral","file":"rectangle.svg","name":{"en":"Rectangle (range)","hi":"रेक्टेंगल (रेंज)"},"what":{"en":"Price moves between a flat support and a flat resistance for a while. Buyers and sellers are balanced inside the box.","hi":"कुछ समय तक कीमत एक सपाट सपोर्ट और सपाट रेज़िस्टेंस के बीच चलती है। बॉक्स के अंदर ख़रीदार और विक्रेता बराबर हैं।"},"where":{"en":"After a trend, as a pause, or at a reversal point.","hi":"ट्रेंड के बाद, ठहराव के रूप में, या पलटाव बिंदु पर।"},"confirm":{"en":"A close outside the box on volume. Above resistance is bullish; below support is bearish.","hi":"वॉल्यूम के साथ बॉक्स के बाहर क्लोज़। रेज़िस्टेंस के ऊपर तेज़ी, सपोर्ट के नीचे मंदी।"},"mistake":{"en":"Trading the middle of the box, where there is no edge.","hi":"बॉक्स के बीच में ट्रेड करना, जहाँ कोई बढ़त नहीं।"}},{"id":"rising-wedge","kind":"chart","bias":"bearish","file":"rising-wedge.svg","name":{"en":"Rising wedge","hi":"राइज़िंग वेज"},"what":{"en":"Higher highs and higher lows, but the two lines converge. Each rally is weaker than the one before.","hi":"ऊँचे हाई और ऊँचे लो, पर दोनों रेखाएँ एक-दूसरे की ओर। हर उछाल पिछले से कमज़ोर।"},"where":{"en":"After a rise, often at the end of an uptrend.","hi":"बढ़त के बाद, अक्सर अपट्रेंड के अंत में।"},"confirm":{"en":"Close below the lower trend line, on volume.","hi":"वॉल्यूम के साथ निचली ट्रेंड लाइन के नीचे क्लोज़।"},"mistake":{"en":"Shorting early while the wedge is still rising. Wait for the breakdown.","hi":"वेज बढ़ते समय जल्दी शॉर्ट करना। ब्रेकडाउन का इंतज़ार करें।"}},{"id":"falling-wedge","kind":"chart","bias":"bullish","file":"falling-wedge.svg","name":{"en":"Falling wedge","hi":"फ़ॉलिंग वेज"},"what":{"en":"Lower highs and lower lows that narrow together. The selling is losing momentum even as price drifts down.","hi":"नीचे के हाई और नीचे के लो जो साथ-साथ संकरे होते हैं। कीमत नीचे खिसकती है, पर बिकवाली की गति घट रही है।"},"where":{"en":"After a fall, often near support.","hi":"गिरावट के बाद, अक्सर सपोर्ट के पास।"},"confirm":{"en":"Close above the upper trend line, on volume.","hi":"वॉल्यूम के साथ ऊपरी ट्रेंड लाइन के ऊपर क्लोज़।"},"mistake":{"en":"Buying inside the wedge before the breakout.","hi":"ब्रेकआउट से पहले वेज के अंदर ख़रीदना।"}},{"id":"pennant","kind":"chart","bias":"bullish","file":"pennant.svg","name":{"en":"Pennant (bull)","hi":"पेनेंट (बुल)"},"what":{"en":"A sharp rise (the pole), then a small symmetrical consolidation where the highs fall and the lows rise, like a small triangle.","hi":"तेज़ उछाल (पोल), फिर छोटा सममित समेकन जहाँ हाई घटते और लो बढ़ते हैं, जैसे छोटा त्रिकोण।"},"where":{"en":"After a strong move, as a continuation.","hi":"मज़बूत चाल के बाद, निरंतरता के रूप में।"},"confirm":{"en":"A breakout in the direction of the pole, on volume.","hi":"पोल की दिशा में वॉल्यूम के साथ ब्रेकआउट।"},"mistake":{"en":"Expecting a pennant after a slow, weak rise. The pole must be sharp.","hi":"धीमी, कमज़ोर चाल के बाद पेनेंट की उम्मीद। पोल तेज़ होना चाहिए।"}},{"id":"triple-top","kind":"chart","bias":"bearish","file":"triple-top.svg","name":{"en":"Triple top","hi":"ट्रिपल टॉप"},"what":{"en":"Three peaks at about the same level, with dips in between. Buyers failed to break the level three times.","hi":"लगभग एक ही स्तर पर तीन शिखर, बीच में गिरावट। ख़रीदार तीन बार उस स्तर को नहीं तोड़ पाए।"},"where":{"en":"After an uptrend, at resistance.","hi":"अपट्रेंड के बाद, रेज़िस्टेंस पर।"},"confirm":{"en":"A close below the support line under the dips, on volume.","hi":"वॉल्यूम के साथ गिरावट के नीचे सपोर्ट रेखा के नीचे क्लोज़।"},"mistake":{"en":"Calling it a triple top before the third peak is confirmed.","hi":"तीसरे शिखर की पुष्टि से पहले इसे ट्रिपल टॉप कहना।"}},{"id":"rounding-bottom","kind":"chart","bias":"bullish","file":"rounding-bottom.svg","name":{"en":"Rounding bottom (saucer)","hi":"राउंडिंग बॉटम (सॉसर)"},"what":{"en":"A slow, rounded U shape. Selling pressure fades gradually and buyers take over.","hi":"धीमा, गोल U आकार। बिकवाली धीरे-धीरे कम होती है और ख़रीदार हावी होते हैं।"},"where":{"en":"After a long decline.","hi":"लंबी गिरावट के बाद।"},"confirm":{"en":"Breakout above the rim (the top of the U), on volume.","hi":"वॉल्यूम के साथ U के ऊपरी किनारे (रिम) के ऊपर ब्रेकआउट।"},"mistake":{"en":"Buying in the middle of the curve before the rim breaks.","hi":"रिम टूटने से पहले कर्व के बीच में ख़रीदना।"}}];
const INDICATORS = [];
const GLOSSARY_TERMS = [{"cat":"technical","term":{"en":"Trend","hi":"ट्रेंड"},"def":{"en":"The general direction of price: up (higher highs and lows), down (lower highs and lows), or sideways.","hi":"कीमत की सामान्य दिशा: ऊपर (ऊँचे हाई और लो), नीचे (नीचे हाई और लो), या साइडवे।"}},{"cat":"technical","term":{"en":"Support","hi":"सपोर्ट"},"def":{"en":"A price level where buying has tended to appear and stop further falls.","hi":"वह कीमत स्तर जहाँ ख़रीदारी दिखी है और आगे गिरावट रुकी है।"}},{"cat":"technical","term":{"en":"Resistance","hi":"रेज़िस्टेंस"},"def":{"en":"A price level where selling has tended to appear and stop further rises.","hi":"वह कीमत स्तर जहाँ बिकवाली दिखी है और आगे बढ़त रुकी है।"}},{"cat":"technical","term":{"en":"Breakout","hi":"ब्रेकआउट"},"def":{"en":"Price moving clearly above resistance or below support, often on higher volume.","hi":"कीमत का रेज़िस्टेंस के ऊपर या सपोर्ट के नीचे साफ़ निकलना, अक्सर ज़्यादा वॉल्यूम के साथ।"}},{"cat":"technical","term":{"en":"Candlestick","hi":"कैंडलस्टिक"},"def":{"en":"A chart element showing open, high, low and close for a period, coloured by direction.","hi":"किसी अवधि का ओपन, हाई, लो और क्लोज़ दिखाने वाला चार्ट तत्व, दिशा के अनुसार रंगीन।"}},{"cat":"technical","term":{"en":"Divergence","hi":"डाइवर्जेंस"},"def":{"en":"When price and an indicator move in opposite directions, such as a new price high with a lower indicator high. It can warn that momentum is fading.","hi":"जब कीमत और इंडिकेटर उलटी दिशा में चलें, जैसे कीमत का नया हाई पर इंडिकेटर का नीचा हाई। यह मोमेंटम कमज़ोर होने की चेतावनी हो सकती है।"}}];
window.MP_PRACTICE = {"candlestick-patterns":[["replay","Start Bar replay in blind mode and stop every time you spot a hammer, engulfing or doji. Write down what the next three candles did.","ब्लाइंड मोड में बार रीप्ले शुरू करें और हर बार हैमर, एंगल्फ़िंग या डोजी दिखने पर रुकें। लिखें कि अगली तीन कैंडल ने क्या किया।"],["screener","Run \"Near 52-week low\" and look for bullish reversal candles at support on the charts of the results.","\"Near 52-week low\" चलाएँ और नतीजों के चार्ट पर सपोर्ट के पास बुलिश रिवर्सल कैंडल खोजें।"],["journal","Take two replay trades based only on a candlestick pattern and record the pattern as the main skill in the journal.","सिर्फ़ कैंडलस्टिक पैटर्न के आधार पर दो रीप्ले ट्रेड लें और जर्नल में पैटर्न को मुख्य स्किल के रूप में दर्ज करें।"]]};
